import { describe, expect, it } from 'vitest'
import { BotEngine } from './engine'
import { radiusAtAngle } from './shape'
import { EXPRESSION_BY_ID } from './expressions'
import { REST_GAZE } from './face'
import { SHAPE_BY_ID } from './skins'
import { SEQUENCE, STATES, type StateId } from './states'

/** Anchor points of a path generated by closedPath (controls ignored). */
function anchors(d: string): Array<[number, number]> {
  const out: Array<[number, number]> = []
  const head = /^M(-?[\d.]+) (-?[\d.]+)/.exec(d)
  if (head) out.push([+head[1]!, +head[2]!])
  for (const seg of d.matchAll(/C[-\d. ]+? (-?[\d.]+) (-?[\d.]+)(?=C|Z)/g)) {
    out.push([+seg[1]!, +seg[2]!])
  }
  return out
}

function footprint(d: string) {
  const pts = anchors(d)
  const xs = pts.map((p) => p[0])
  const ys = pts.map((p) => p[1])
  return {
    w: (Math.max(...xs) - Math.min(...xs)) / 100,
    h: (Math.max(...ys) - Math.min(...ys)) / 100
  }
}

/** Footprints measured on the video (width x height, in ball diameters). */
const FOOTPRINTS: Array<[StateId, number, number, number, number]> = [
  // etat,        date,  largeur, hauteur, tolerance
  ['idle', 0.5, 2.0, 2.0, 0.05],
  ['sleep', 0.6, 0.317, 0.317, 0.03]
]

describe('silhouettes', () => {
  for (const [id, t, w, h, tol] of FOOTPRINTS) {
    it(`"${id}" has the footprint measured on the video`, () => {
      const e = new BotEngine(100, id)
      const { w: gw, h: gh } = footprint(e.sample(t).bodyPath)
      expect(Math.abs(gw - w)).toBeLessThan(tol)
      expect(Math.abs(gh - h)).toBeLessThan(tol)
    })
  }

  it('the ball at rest is a circle, not an oval', () => {
    const e = new BotEngine(100, 'idle')
    const { w, h } = footprint(e.sample(0.5).bodyPath)
    expect(Math.abs(w - h)).toBeLessThan(0.03)
  })

})

describe('engine', () => {
  it('is a pure function of time: two reads at the same time are identical', () => {
    const a = new BotEngine(100, 'thinking')
    const b = new BotEngine(100, 'thinking')
    expect(a.sample(1.3).bodyPath).toBe(b.sample(1.3).bodyPath)
    // and reading a past time again gives the same frame
    const first = a.sample(0.7).bodyPath
    a.sample(2.5)
    expect(a.sample(0.7).bodyPath).toBe(first)
  })

  it('stays replayable DURING a fade between states', () => {
    // the trap: purging the previous state once the fade is over makes this
    // time unrecoverable, and the fade disappears on replay
    const e = new BotEngine(100, 'idle')
    e.setState('sleep', 1)
    const during = e.sample(1.2).bodyPath
    e.sample(3)
    expect(e.sample(1.2).bodyPath).toBe(during)
  })

  it('does not fly off on a time before the state change', () => {
    // before the change there is nothing to fade: we must see the outgoing state
    const e = new BotEngine(100, 'idle')
    const before = e.sample(0.5).bodyPath
    e.setState('sleep', 1)
    expect(e.sample(0.5).bodyPath).toBe(before)
  })

  it('really animates: the shape changes between two times', () => {
    const e = new BotEngine(100, 'thinking')
    const paths = [0.1, 0.4, 0.8, 1.2].map((t) => e.sample(t).bodyPath)
    expect(new Set(paths).size).toBe(paths.length)
  })

  it('interpolates the silhouette during a transition, without a jump', () => {
    const e = new BotEngine(100, 'idle')
    e.setState('sleep', 1)
    const widths = [1, 1.1, 1.2, 1.3, 1.4].map((t) => footprint(e.sample(t).bodyPath).w)
    // strictly decreasing: the ball shrinks to the small sleeping ball
    for (let i = 1; i < widths.length; i++) {
      expect(widths[i]!).toBeLessThan(widths[i - 1]!)
    }
    expect(widths[0]!).toBeCloseTo(2, 1)
    expect(footprint(e.sample(2).bodyPath).w).toBeCloseTo(0.317, 1)
  })

  it('never lets the body overflow the viewBox', () => {
    for (const s of STATES) {
      const e = new BotEngine(100, s.id)
      for (const t of [0.2, 0.9, 1.8, 3]) {
        const pts = anchors(e.sample(t).bodyPath)
        for (const [x, y] of pts) {
          expect(Math.abs(x)).toBeLessThan(158)
          expect(Math.abs(y)).toBeLessThan(158)
        }
      }
    }
  })
})

describe('shape personnalisee', () => {
  const radii = (id: string) => SHAPE_BY_ID.get(id)!.radii
  const height = (e: BotEngine, t: number) => footprint(e.sample(t).bodyPath).h

  it('replaces the silhouette of resting states', () => {
    const round = new BotEngine(100, 'idle')
    const drop = new BotEngine(100, 'idle', radii('drop'))
    expect(drop.sample(1).bodyPath).not.toBe(round.sample(1).bodyPath)
  })

  it('leaves alone the states that draw their own shape', () => {
    for (const id of ['thinking', 'sleep'] as const) {
      const bare = new BotEngine(100, id)
      const dressed = new BotEngine(100, id, radii('drop'))
      expect(dressed.sample(1).bodyPath).toBe(bare.sample(1).bodyPath)
    }
  })

  it('morphs to the new shape instead of jumping', () => {
    const e = new BotEngine(100, 'idle', radii('circle'))
    // the circle is 2.0 high, the capsule 1.24: height tells them apart
    expect(height(e, 1)).toBeCloseTo(2, 1)
    e.setShape(radii('capsule'), 1)

    const steps = [1.06, 1.14, 1.26].map((t) => height(e, t))
    // strictly decreasing, and never already there
    for (let i = 1; i < steps.length; i++) {
      expect(steps[i]!).toBeLessThan(steps[i - 1]!)
    }
    expect(steps[0]!).toBeLessThan(2)
    expect(steps[steps.length - 1]!).toBeGreaterThan(1.24)

    // arrives after the morph duration
    expect(height(e, 1 + BotEngine.SHAPE_MORPH + 0.05)).toBeCloseTo(1.24, 1)
  })

  it('stays a pure function of time during a shape morph', () => {
    const e = new BotEngine(100, 'idle', radii('circle'))
    e.setShape(radii('capsule'), 1)
    const middle = e.sample(1.1).bodyPath
    // we go past the end of the morph, then read the past time again
    e.sample(3)
    expect(e.sample(1.1).bodyPath).toBe(middle)
  })

  it('keeps the eyes inside the silhouette on a non circular shape', () => {
    for (const id of ['cloud', 'capsule', 'drop', 'triangle', 'squircle'] as const) {
      const f = new BotEngine(100, 'idle', radii(id)).sample(1)
      expect(f.eyes).toHaveLength(2)
      for (const eye of f.eyes) {
        const parts = /matrix\(([^)]+)\)/.exec(eye.matrix)![1]!.split(',').map(Number)
        const ex = parts[4]!
        const ey = parts[5]!
        const edge = radiusAtAngle(radii(id), Math.atan2(ey, ex)) * 100
        // the eye center must stay clearly inside the outline
        expect(Math.hypot(ex, ey)).toBeLessThan(edge)
      }
    }
  })
})

describe('states', () => {
  /**
   * The sequence is the CATALOG: the 5 states with a face measured on the video, those the palette offers and the
   * sheet shows. Any state outside the sequence is an interface transition, chosen and not measured: it must never
   * appear in the catalog, and that is exactly what we check.
   */
  it('keeps the 5 states with a face in the sequence, and nothing else', () => {
    expect(SEQUENCE).toHaveLength(5)
    expect(new Set(SEQUENCE).size).toBe(5)
    for (const id of SEQUENCE) expect(STATES.some((s) => s.id === id), id).toBe(true)
  })

  it('draws the rings of the entry transition in front of AND behind the body', () => {
    const f = new BotEngine(100, 'swirl').sample(0.6)
    expect(f.arcs.length).toBeGreaterThan(1)
    expect(f.arcs.some((a) => a.back.length > 0)).toBe(true)
    expect(f.arcs.some((a) => a.front.length > 0)).toBe(true)
  })

  it('keeps interface transitions out of the catalog', () => {
    const outSequence = STATES.filter((s) => !SEQUENCE.includes(s.id)).map((s) => s.id)
    expect(outSequence).toEqual(['swirl'])
  })

  it('shows the face on states with a face, hides it on the others', () => {
    const withIt: StateId[] = ['idle', 'wink', 'wide']
    const without: StateId[] = ['thinking', 'sleep']
    for (const id of withIt) expect(new BotEngine(100, id).sample(0.9).eyes.length).toBe(2)
    for (const id of without) expect(new BotEngine(100, id).sample(0.9).eyes.length).toBe(0)
  })
})

describe('gaze that follows the pointer', () => {
  /** Abscissa of the inner eye, in viewBox px. */
  const eyeX = (e: BotEngine, t: number) => +/matrix\([^,]+,[^,]+,[^,]+,[^,]+,(-?[\d.]+)/
    .exec(e.sample(t).eyes[0]!.matrix)![1]!

  /** Amplitude of its move over a time range. */
  function amplitude(e: BotEngine, from: number, a: number) {
    const xs: number[] = []
    for (let t = from; t <= a; t += 0.1) xs.push(eyeX(e, t))
    return Math.max(...xs) - Math.min(...xs)
  }

  it('does not touch the gaze as long as no target is set', () => {
    const bare = new BotEngine(100, 'idle')
    const aims = new BotEngine(100, 'idle')
    aims.setLook(null, 0)
    expect(aims.sample(1).eyes[0]!.matrix).toBe(bare.sample(1).eyes[0]!.matrix)
  })

  it('turns the gaze to the aimed yaw, in absolute terms', () => {
    const right = new BotEngine(100, 'idle')
    const left = new BotEngine(100, 'idle')
    right.setLook({ yaw: 45, pitch: 0, mix: 1, spin: 0, wander: 0 }, 0)
    left.setLook({ yaw: -45, pitch: 0, mix: 1, spin: 0, wander: 0 }, 0)
    const t = 1 + BotEngine.LOOK_MORPH
    expect(eyeX(right, t)).toBeGreaterThan(eyeX(left, t) + 40)
  })

  it('replaces the yaw of the pose instead of adding to it', () => {
    // That is what makes an expression change smooth: the caller does not have to
    // subtract the expression's yaw, so it does not need to know its
    // value, which during a morph is not the final one yet.
    // Two expressions that differ ONLY by their yaw: the abscissa of an eye
    // also depends on pitch and eye gap, so varying them
    // together would prove nothing.
    const model = EXPRESSION_BY_ID.get('neutral')!
    const gauchier = { ...model, gaze: { ...model.gaze, yaw: -30 } }
    const droitier = { ...model, gaze: { ...model.gaze, yaw: 60 } }
    const circle = SHAPE_BY_ID.get('circle')!.radii

    const a = new BotEngine(100, 'idle', circle, gauchier)
    const b = new BotEngine(100, 'idle', circle, droitier)
    // without a target, the two clearly look in different places
    expect(Math.abs(eyeX(a, 1) - eyeX(b, 1))).toBeGreaterThan(40)

    a.setLook({ yaw: -26, pitch: 0, mix: 1, spin: 0, wander: 0 }, 1)
    b.setLook({ yaw: -26, pitch: 0, mix: 1, spin: 0, wander: 0 }, 1)
    // ...and the same aimed yaw puts them exactly at the same place
    const t = 1 + BotEngine.LOOK_MORPH
    expect(eyeX(a, t)).toBeCloseTo(eyeX(b, t), 5)
  })

  it('travels the requested turn without changing where it lands', () => {
    const direct = new BotEngine(100, 'idle')
    const turns = new BotEngine(100, 'idle')
    direct.setLook({ yaw: -26, pitch: 0, mix: 1, spin: 0, wander: 0 }, 0)
    turns.setLook({ yaw: -26, pitch: 0, mix: 1, spin: 360, wander: 0 }, 0)
    const t = 1 + BotEngine.LOOK_MORPH
    // a full turn is the same angle: the frame must be identical to the pixel
    expect(turns.sample(t).eyes[0]!.matrix).toBe(direct.sample(t).eyes[0]!.matrix)
    // ...while at half turn the face points away from the viewer
    const mi = new BotEngine(100, 'idle')
    mi.setLook({ yaw: -26, pitch: 0, mix: 1, spin: 180, wander: 0 }, 0)
    expect(mi.sample(t).eyes).toHaveLength(0)
  })

  it('keeps both eyes visible at extreme amplitudes', () => {
    // beyond that, the outer eye goes behind the sphere's limb and the
    // engine removes it: the stop of <mochi-bot> must stay below
    for (const yaw of [-42, -26, -10]) {
      for (const pitch of [-3, 10, 23]) {
        const e = new BotEngine(100, 'idle')
        e.setLook({ yaw, pitch, mix: 1, spin: 0, wander: 0 }, 0)
        expect(e.sample(1).eyes, `yaw ${yaw} pitch ${pitch}`).toHaveLength(2)
      }
    }
  })

  it('turns off the automatic drift when the pointer drives', () => {
    const free = new BotEngine(100, 'idle')
    const held = new BotEngine(100, 'idle')
    held.setLook({ yaw: REST_GAZE.yaw, pitch: 0, mix: 1, spin: 0, wander: 0 }, 0)

    // Same target as the resting gaze: whatever motion remains
    // is ONLY the drift. It must have stopped, except that the
    // body float (±0.006 radius, `float`) is not concerned.
    expect(amplitude(held, 1, 8)).toBeLessThan(2)
    expect(amplitude(free, 1, 8)).toBeGreaterThan(5 * amplitude(held, 1, 8))
  })

  it('goes back to the state\'s gaze when the target is released', () => {
    const bare = new BotEngine(100, 'idle')
    const e = new BotEngine(100, 'idle')
    e.setLook({ yaw: -20, pitch: -10, mix: 1, spin: 0, wander: 0 }, 0)
    e.sample(1)
    e.setLook(null, 1)
    // the return is gradual, then complete
    expect(eyeX(e, 1.05)).not.toBeCloseTo(eyeX(bare, 1.05), 1)
    const finished = 1 + BotEngine.LOOK_MORPH
    expect(eyeX(e, finished)).toBeCloseTo(eyeX(bare, finished), 5)
  })

  it('stays a pure function of time during the catch-up', () => {
    const e = new BotEngine(100, 'idle')
    e.setLook({ yaw: -18, pitch: -8, mix: 1, spin: 0, wander: 0 }, 1)
    const middle = e.sample(1.1).eyes[0]!.matrix
    // reading a past time again must give exactly the same frame
    e.sample(3)
    expect(e.sample(1.1).eyes[0]!.matrix).toBe(middle)
  })

  it('leaves the drift alone on thumbnails, which never aim', () => {
    // a frozen thumbnail does not call setLook: its gaze must drift as before
    const e = new BotEngine(100, 'idle')
    expect(amplitude(e, 0, 6)).toBeGreaterThan(4)
  })
})

describe('gaze robustness', () => {
  it('refuses a non-finite target rather than remembering it', () => {
    /**
     * The engine KEEPS the last target: a `NaN` set once would spread to every frame and the bot would never rest
     * again. It really happened: `getBoundingClientRect` on a zero-size box gives `0 / 0` in the caller.
     */
    const sain = new BotEngine(100, 'idle')
    const e = new BotEngine(100, 'idle')
    e.setLook({ yaw: NaN, pitch: 10, mix: 1, spin: 0, wander: 0 }, 0)
    expect(e.sample(1).eyes[0]!.matrix).toBe(sain.sample(1).eyes[0]!.matrix)

    // and a sound target set afterwards still works
    e.setLook({ yaw: -26, pitch: 10, mix: 1, spin: 0, wander: 0 }, 1)
    expect(e.sample(1 + BotEngine.LOOK_MORPH).eyes[0]!.matrix).not.toBe(
      sain.sample(1 + BotEngine.LOOK_MORPH).eyes[0]!.matrix
    )
  })

  it('keeps a turned head alive when no pointer drives it', () => {
    /**
     * Fixed regression: `mix` turned the drift off at the same time as it took the direction. Arriving on the tab by
     * keyboard or touch then gave a fully frozen avatar, which contradicts the definition of the resting state ("gaze
     * drift and blinks").
     */
    const eyeX = (e: BotEngine, t: number) => +/matrix\([^,]+,[^,]+,[^,]+,[^,]+,(-?[\d.]+)/
      .exec(e.sample(t).eyes[0]!.matrix)![1]!
    const amplitude = (e: BotEngine) => {
      const xs: number[] = []
      for (let t = 1; t <= 8; t += 0.1) xs.push(eyeX(e, t))
      return Math.max(...xs) - Math.min(...xs)
    }

    const withoutPointer = new BotEngine(100, 'idle')
    withoutPointer.setLook({ yaw: -26, pitch: 10, mix: 1, spin: 0, wander: 1 }, 0)
    const withPointer = new BotEngine(100, 'idle')
    withPointer.setLook({ yaw: -26, pitch: 10, mix: 1, spin: 0, wander: 0 }, 0)

    // the head is turned in both cases...
    expect(eyeX(withoutPointer, 1)).toBeLessThan(0)
    expect(eyeX(withPointer, 1)).toBeLessThan(0)
    // ...but only the one nobody drives keeps drifting
    expect(amplitude(withoutPointer)).toBeGreaterThan(5 * amplitude(withPointer))
  })
})

/**
 * `reset`: start again on a state WITHOUT history.
 *
 * It is one more public method on what must become an API, so it deserves its direct test and not only the indirect
 * coverage of the off-screen player.
 */
describe('reset', () => {
  it('forgets the previous state, where setState keeps it to fade it', () => {
    const withFade = new BotEngine(100, 'idle')
    withFade.setState('sleep', 0)
    const remis = new BotEngine(100, 'idle')
    remis.reset('sleep', 0)

    // at the start of the morph, one still mixes idle, the other is already the small ball
    expect(withFade.sample(0).bodyPath).not.toBe(remis.sample(0).bodyPath)
    // and sleep alone is indeed what a new engine on `sleep` renders
    expect(remis.sample(0).bodyPath).toBe(new BotEngine(100, 'sleep').sample(0).bodyPath)
  })

  /*
   * Compared at the same ABSOLUTE time, not a pose timed at 0 against one timed at 5: the resting drift depends on
   * absolute time, so two different times never give the same path, even on a state with a fixed pose. The comparison
   * would say nothing.
   */
  it('times the state where it is told', () => {
    const tot = new BotEngine(100, 'idle')
    tot.reset('sleep', 0)
    const late = new BotEngine(100, 'idle')
    late.reset('sleep', 5)
    // the sleep bounce is periodic: at the same absolute time, one is at 5 s and the other at the start
    expect(tot.sample(5).bodyPath).not.toBe(late.sample(5).bodyPath)
    expect(late.state).toBe('sleep')
  })

  it('leaves sample a pure function of time', () => {
    const e = new BotEngine(100, 'idle')
    e.reset('thinking', 0)
    const tot = e.sample(0.3).bodyPath
    e.sample(9)
    expect(e.sample(0.3).bodyPath).toBe(tot)
  })
})

/**
 * A state change arriving DURING a fade.
 *
 * The engine keeps a single history slot, so the origin of the new mix became the FULL pose of the state being left,
 * instead of the half-mixed frame on screen: a jump. It now mixes from the composite pose frozen at the time of the
 * change.
 *
 * Measured: the move of an eye over the two frames after a change. A SPACED change gives 10 to 14 px, on purpose (the
 * `easeOutQuint` measured on the video starts steep). What was not intended is the 26 to 43 px of a change mid-fade.
 */
describe('state change during a fade', () => {
  const IMAGE = 1 / 60

  /** Max move of an eye over the two frames after `at`. */
  function jumpAfter(changements: Array<[StateId, number]>, at: number) {
    const e = new BotEngine(100, 'idle')
    const distances: Array<{ t: number; d: number[] }> = []
    let i = 0
    for (let t = 0; t <= at + 4 * IMAGE; t += IMAGE) {
      while (i < changements.length && changements[i]![1] <= t + 1e-9) {
        e.setState(changements[i]![0], changements[i]![1])
        i++
      }
      distances.push({
        t,
        d: e.sample(t).eyes.map((y) => {
          const n = y.matrix.match(/-?\d+\.?\d*/g)!.map(Number)
          return Math.hypot(n[4]!, n[5]!)
        })
      })
    }
    let worst = 0
    for (let k = 1; k < distances.length; k++) {
      const a = distances[k - 1]!
      const b = distances[k]!
      if (a.d.length !== b.d.length || b.t <= at || b.t > at + 2.5 * IMAGE) continue
      worst = Math.max(worst, ...a.d.map((v, j) => Math.abs(v - b.d[j]!)))
    }
    return worst
  }

  /** Reference: the same change, but spaced. That is the normal motion. */
  const NORMAL = 14

  it('does not jump more than a spaced change', () => {
    const space = jumpAfter([['wide', 0.5], ['idle', 2]], 2)
    expect(space).toBeLessThan(NORMAL)

    // 100 ms after the first, so in the middle of a 0.55 s fade
    expect(jumpAfter([['wide', 0.5], ['idle', 0.6]], 0.6)).toBeLessThanOrEqual(space)
  })

  it('holds over chained changes', () => {
    const suite: Array<[StateId, number]> = [
      ['wide', 0.5],
      ['idle', 0.55],
      ['sleep', 0.6],
      ['thinking', 0.65],
      ['wink', 0.7]
    ]
    for (const [, at] of suite.slice(1)) {
      expect(jumpAfter(suite, at), `changement a ${at}s`).toBeLessThan(NORMAL)
    }
  })

  /**
   * And SPACED playback does not change: montage blocks last at least the longest fade, so nothing is ever frozen
   * there. Checked on the full sequence, frame by frame: that is what protects the measured animations.
   */
  it('changes nothing to a spaced playback', () => {
    const suite: Array<[StateId, number]> = [
      ['thinking', 1],
      ['wink', 2],
      ['sleep', 3]
    ]
    const withHistory = new BotEngine(100, 'idle')
    let i = 0
    const images: string[] = []
    for (let t = 0; t < 4; t += IMAGE) {
      while (i < suite.length && suite[i]![1] <= t + 1e-9) {
        withHistory.setState(suite[i]![0], suite[i]![1])
        i++
      }
      images.push(withHistory.sample(t).bodyPath)
    }
    // no empty frame, and the `sleep` bounce still moves while fading
    expect(images.every((p) => p.length > 0)).toBe(true)
    expect(new Set(images.slice(-12)).size).toBeGreaterThan(1)
  })
})
